// server/src/events/socket-handler.ts
import { Server, Socket } from 'socket.io';
import { Message } from '../models/message.model';
import { Conversation } from '../models/conversation.model';
import { User } from '../models/user.model';

export function setupSocketHandlers(io: Server) {
  io.on('connection', async (socket: Socket) => {
    const userId = socket.data.userId;
    console.log(`User connected: ${userId}`);

    // Kullanıcıyı online yap
    await User.findByIdAndUpdate(userId, { isOnline: true });

    // Kullanıcının konuşma odalarına katıl
    const conversations = await Conversation.find({ participants: userId });
    conversations.forEach((conv) => {
      socket.join(conv.id);
    });

    // Online durumunu bildir
    socket.broadcast.emit('user:online', { userId });

    // Mesaj gönderme
    socket.on('message:send', async (data, callback) => {
      try {
        const { conversationId, content, type = 'text' } = data;

        const message = await Message.create({
          conversationId,
          sender: userId,
          content,
          type,
          readBy: [userId],
        });

        await Conversation.findByIdAndUpdate(conversationId, {
          lastMessage: message.id,
          lastActivity: new Date(),
        });

        const populated = await message.populate('sender', 'name avatar');

        // Odadaki herkese gönder
        io.to(conversationId).emit('message:received', populated);

        // Başarı callback
        callback({ status: 'ok', messageId: message.id });
      } catch (error) {
        callback({ status: 'error', message: 'Mesaj gönderilemedi' });
      }
    });

    // Yazıyor bildirimi
    socket.on('typing:start', (data) => {
      socket.to(data.conversationId).emit('typing:update', {
        userId,
        conversationId: data.conversationId,
        isTyping: true,
      });
    });

    socket.on('typing:stop', (data) => {
      socket.to(data.conversationId).emit('typing:update', {
        userId,
        conversationId: data.conversationId,
        isTyping: false,
      });
    });

    // Mesaj okundu
    socket.on('message:read', async (data) => {
      await Message.updateMany(
        {
          conversationId: data.conversationId,
          sender: { $ne: userId },
          readBy: { $nin: [userId] },
        },
        { $addToSet: { readBy: userId } }
      );

      socket.to(data.conversationId).emit('message:read:update', {
        conversationId: data.conversationId,
        userId,
      });
    });

    // Bağlantı kopma
    socket.on('disconnect', async () => {
      await User.findByIdAndUpdate(userId, {
        isOnline: false,
        lastSeen: new Date(),
      });
      socket.broadcast.emit('user:offline', { userId });
      console.log(`User disconnected: ${userId}`);
    });
  });
}

