import Redis from 'ioredis';
import { config } from './config';

export const redis = new Redis(config.redisUrl);
export const pubClient = new Redis(config.redisUrl);
export const subClient = pubClient.duplicate();

// Kullanıcı online durumu Redis'te sakla
export async function setUserOnline(userId: string, socketId: string) {
  await redis.hset('online_users', userId, socketId);
}

export async function setUserOffline(userId: string) {
  await redis.hdel('online_users', userId);
}

export async function getOnlineUsers(): Promise<string[]> {
  const users = await redis.hkeys('online_users');
  return users;
}

