import { Conversation } from '../models/conversation.model';
import { User } from '../models/user.model';
import mongoose from 'mongoose';

export class ConversationService {
  async getOrCreateDirect(userId: string, targetUserId: string) {
    // Mevcut konuşmayı bul
    let conversation = await Conversation.findOne({
      type: 'direct',
      participants: { $all: [userId, targetUserId], $size: 2 },
    }).populate('participants', 'name avatar isOnline lastSeen')
      .populate('lastMessage');

    if (!conversation) {
      conversation = await Conversation.create({
        type: 'direct',
        participants: [userId, targetUserId],
      });
      conversation = await conversation.populate('participants', 'name avatar isOnline lastSeen');
    }

    return conversation;
  }

  async createGroup(userId: string, name: string, participantIds: string[]) {
    const allParticipants = [...new Set([userId, ...participantIds])];

    const conversation = await Conversation.create({
      type: 'group',
      name,
      participants: allParticipants,
    });

    return conversation.populate('participants', 'name avatar isOnline lastSeen');
  }

  async getUserConversations(userId: string) {
    return Conversation.find({ participants: userId })
      .populate('participants', 'name avatar isOnline lastSeen')
      .populate('lastMessage')
      .sort({ lastActivity: -1 })
      .lean();
  }
}

