import { Message } from '../models/message.model';
import mongoose from 'mongoose';

export class MessageService {
  async getMessages(
    conversationId: string,
    cursor?: string,
    limit: number = 50
  ) {
    const query: any = { conversationId };

    if (cursor) {
      // Cursor'dan önceki mesajları getir (daha eski)
      query.createdAt = { $lt: new Date(cursor) };
    }

    const messages = await Message.find(query)
      .sort({ createdAt: -1 })
      .limit(limit + 1) // Bir fazla getir (sonraki sayfa var mı kontrol)
      .populate('sender', 'name avatar')
      .lean();

    const hasMore = messages.length > limit;
    if (hasMore) messages.pop(); // Fazla olan elemanı çıkar

    return {
      messages: messages.reverse(), // Kronolojik sıra
      hasMore,
      nextCursor: hasMore ? messages[0]?.createdAt?.toISOString() : null,
    };
  }

  async searchMessages(conversationId: string, query: string) {
    return Message.find({
      conversationId,
      content: { $regex: query, $options: 'i' },
    })
      .sort({ createdAt: -1 })
      .limit(20)
      .populate('sender', 'name avatar')
      .lean();
  }
}

