async getUnreadCount(userId: string, conversationId: string): Promise<number> {
  return Message.countDocuments({
    conversationId,
    sender: { $ne: userId },
    readBy: { $nin: [userId] },
  });
}

async getUnreadCounts(userId: string): Promise<Record<string, number>> {
  const conversations = await Conversation.find({ participants: userId }).lean();
  const counts: Record<string, number> = {};

  for (const conv of conversations) {
    counts[conv._id.toString()] = await this.getUnreadCount(userId, conv._id.toString());
  }

  return counts;
}

