import { Router } from 'express';
import { authenticate } from '../middleware/auth';
import { ConversationService } from '../services/conversation.service';
import { MessageService } from '../services/message.service';

const router = Router();
const conversationService = new ConversationService();
const messageService = new MessageService();

router.use(authenticate);

// Konuşma listesi
router.get('/', async (req, res, next) => {
  try {
    const conversations = await conversationService.getUserConversations(req.userId!);
    const unreadCounts = await messageService.getUnreadCounts(req.userId!);

    const enriched = conversations.map((conv: any) => ({
      ...conv,
      unreadCount: unreadCounts[conv._id.toString()] || 0,
    }));

    res.json({ status: 'success', data: enriched });
  } catch (error) {
    next(error);
  }
});

// Mesaj geçmişi (cursor-based pagination)
router.get('/:id/messages', async (req, res, next) => {
  try {
    const { cursor, limit } = req.query;
    const result = await messageService.getMessages(
      req.params.id,
      cursor as string,
      parseInt(limit as string) || 50
    );
    res.json({ status: 'success', data: result });
  } catch (error) {
    next(error);
  }
});

