import { useEffect } from 'react';
import { useSocketStore } from '../stores/socket-store';
import { useChatStore } from '../stores/chat-store';
import { ConversationList } from '../components/conversation-list';
import { ChatWindow } from '../components/chat-window';
import { api } from '../lib/api';

export function ChatPage() {
  const { socket } = useSocketStore();
  const { activeConversation, setConversations, addMessage, setTyping } = useChatStore();

  useEffect(() => {
    // Konuşma listesini yükle
    api.get('/conversations').then(({ data }) => {
      setConversations(data.data);
    });
  }, []);

  useEffect(() => {
    if (!socket) return;

    // Real-time event listener'lar
    socket.on('message:received', (message) => {
      addMessage(message.conversationId, message);
    });

    socket.on('typing:update', ({ userId, conversationId, isTyping }) => {
      setTyping(conversationId, userId, isTyping);
    });

    return () => {
      socket.off('message:received');
      socket.off('typing:update');
    };
  }, [socket]);

  return (
    <div className="flex h-screen">
      <div className="w-80 border-r border-gray-200 dark:border-gray-800">
        <ConversationList />
      </div>
      <div className="flex-1">
        {activeConversation ? (
          <ChatWindow conversationId={activeConversation} />
        ) : (
          <div className="flex h-full items-center justify-center text-gray-400">
            Bir konuşma seçin
          </div>
        )}
      </div>
    </div>
  );
}

// client/src/components/chat-window.tsx
import { useState, useEffect, useRef, useCallback } from 'react';
import { useSocketStore } from '../stores/socket-store';
import { useChatStore } from '../stores/chat-store';
import { api } from '../lib/api';
import { MessageBubble } from './message-bubble';

export function ChatWindow({ conversationId }: { conversationId: string }) {
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const { socket } = useSocketStore();
  const { messages, typingUsers, setMessages, addMessage } = useChatStore();

  const conversationMessages = messages[conversationId] || [];
  const typing = typingUsers[conversationId] || [];

  useEffect(() => {
    // Mesaj geçmişini yükle
    setIsLoading(true);
    api.get(`/conversations/${conversationId}/messages`)
      .then(({ data }) => setMessages(conversationId, data.data.messages))
      .finally(() => setIsLoading(false));

    // Mesajları okundu olarak işaretle
    socket?.emit('message:read', { conversationId });
  }, [conversationId]);

  useEffect(() => {
    // Yeni mesajda otomatik scroll
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [conversationMessages.length]);

  const sendMessage = useCallback(() => {
    if (!input.trim() || !socket) return;

    socket.emit('message:send', {
      conversationId,
      content: input.trim(),
      type: 'text',
    }, (response: any) => {
      if (response.status !== 'ok') {
        console.error('Mesaj gönderilemedi');
      }
    });

    setInput('');
    socket.emit('typing:stop', { conversationId });
  }, [input, socket, conversationId]);

  const handleTyping = useCallback(() => {
    socket?.emit('typing:start', { conversationId });
  }, [socket, conversationId]);

  return (
    <div className="flex h-full flex-col">
      {/* Header */}
      <div className="border-b px-4 py-3">
        <h2 className="font-semibold">Konuşma</h2>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {isLoading ? (
          <div className="text-center text-gray-400">Yükleniyor...</div>
        ) : (
          conversationMessages.map((msg: any) => (
            <MessageBubble key={msg._id} message={msg} />
          ))
        )}

        {typing.length > 0 && (
          <div className="text-sm text-gray-400 italic">
            {typing.length === 1 ? 'Yazıyor...' : `${typing.length} kişi yazıyor...`}
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <div className="border-t p-4">
        <div className="flex gap-2">
          <textarea
            value={input}
            onChange={(e) => {
              setInput(e.target.value);
              handleTyping();
            }}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
              }
            }}
            placeholder="Mesajınızı yazın... (@ai ile AI asistanı kullanın)"
            className="flex-1 resize-none rounded-lg border p-2 focus:border-blue-500 focus:outline-none dark:border-gray-700 dark:bg-gray-800"
            rows={1}
          />
          <button
            onClick={sendMessage}
            disabled={!input.trim()}
            className="rounded-lg bg-blue-600 px-4 py-2 text-white hover:bg-blue-700 disabled:opacity-50"
          >
            Gönder
          </button>
        </div>
      </div>
    </div>
  );
}

