import { useAuth } from '../contexts/auth-context';

export function MessageBubble({ message }: { message: any }) {
  const { user } = useAuth();
  const isOwn = message.sender._id === user?.id || message.sender === user?.id;
  const isAI = message.type === 'ai_response';

  return (
    <div className={`flex ${isOwn ? 'justify-end' : 'justify-start'}`}>
      <div className="flex max-w-[70%] gap-2">
        {!isOwn && (
          <div className="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full bg-gray-200 text-sm font-medium text-gray-600">
            {isAI ? 'AI' : message.sender.name?.[0]?.toUpperCase()}
          </div>
        )}

        <div>
          {!isOwn && (
            <p className="mb-1 text-xs text-gray-500">
              {isAI ? 'AI Asistan' : message.sender.name}
            </p>
          )}

          <div
            className={`rounded-2xl px-4 py-2 ${
              isOwn
                ? 'bg-blue-600 text-white'
                : isAI
                ? 'border border-purple-200 bg-purple-50 text-gray-800 dark:border-purple-800 dark:bg-purple-900/20 dark:text-gray-200'
                : 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200'
            }`}
          >
            <p className="whitespace-pre-wrap text-sm">{message.content}</p>
          </div>

          <div className={`mt-1 flex items-center gap-1 text-xs text-gray-400 ${isOwn ? 'justify-end' : ''}`}>
            <span>
              {new Date(message.createdAt).toLocaleTimeString('tr-TR', {
                hour: '2-digit',
                minute: '2-digit',
              })}
            </span>
            {isOwn && (
              <span>
                {message.readBy?.length > 1 ? '✓✓' : '✓'}
              </span>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

