import { useState, useCallback, useRef, useEffect } from 'react';
import { api } from '../lib/api';
import { useChatStore } from '../stores/chat-store';

export function useInfiniteMessages(conversationId: string) {
  const [hasMore, setHasMore] = useState(true);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const cursorRef = useRef<string | null>(null);
  const { messages, setMessages } = useChatStore();
  const observerRef = useRef<HTMLDivElement>(null);

  const loadMore = useCallback(async () => {
    if (isLoadingMore || !hasMore) return;

    setIsLoadingMore(true);
    try {
      const params = cursorRef.current
        ? `?cursor=${cursorRef.current}&limit=50`
        : '?limit=50';

      const { data } = await api.get(
        `/conversations/${conversationId}/messages${params}`
      );

      const newMessages = data.data.messages;
      const existing = messages[conversationId] || [];

      setMessages(conversationId, [...newMessages, ...existing]);
      setHasMore(data.data.hasMore);
      cursorRef.current = data.data.nextCursor;
    } catch (error) {
      console.error('Mesaj yükleme hatası:', error);
    } finally {
      setIsLoadingMore(false);
    }
  }, [conversationId, isLoadingMore, hasMore]);

  // IntersectionObserver ile scroll izleme
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasMore && !isLoadingMore) {
          loadMore();
        }
      },
      { threshold: 0.1 }
    );

    if (observerRef.current) {
      observer.observe(observerRef.current);
    }

    return () => observer.disconnect();
  }, [loadMore, hasMore, isLoadingMore]);

  return { isLoadingMore, hasMore, observerRef, loadMore };
}

