import OpenAI from 'openai';
import { config } from '../utils/config';

const openai = new OpenAI({ apiKey: config.openaiApiKey });

const SYSTEM_PROMPT = `Sen yardımsever bir AI asistansın. Chat uygulamasında kullanıcılara yardım ediyorsun.
Kurallar:
- Kısa ve öz cevaplar ver (maksimum 500 kelime)
- Kod sorularında syntax highlighting için markdown kullan
- Türkçe cevap ver (teknik terimler İngilizce kalabilir)
- Zararlı veya uygunsuz içerik üretme
- Emin olmadığın konularda bunu belirt`;

export class AIService {
  async generateResponse(userMessage: string, conversationHistory: any[] = []) {
    const messages: OpenAI.Chat.ChatCompletionMessageParam[] = [
      { role: 'system', content: SYSTEM_PROMPT },
      ...conversationHistory.slice(-10).map((msg) => ({
        role: msg.type === 'ai_response' ? 'assistant' as const : 'user' as const,
        content: msg.content,
      })),
      { role: 'user', content: userMessage },
    ];

    const completion = await openai.chat.completions.create({
      model: 'gpt-4o-mini',
      messages,
      max_tokens: 1000,
      temperature: 0.7,
    });

    return completion.choices[0].message.content || 'Yanıt oluşturulamadı.';
  }

  async generateStreamingResponse(
    userMessage: string,
    conversationHistory: any[] = [],
    onToken: (token: string) => void
  ) {
    const messages: OpenAI.Chat.ChatCompletionMessageParam[] = [
      { role: 'system', content: SYSTEM_PROMPT },
      ...conversationHistory.slice(-10).map((msg) => ({
        role: msg.type === 'ai_response' ? 'assistant' as const : 'user' as const,
        content: msg.content,
      })),
      { role: 'user', content: userMessage },
    ];

    const stream = await openai.chat.completions.create({
      model: 'gpt-4o-mini',
      messages,
      max_tokens: 1000,
      temperature: 0.7,
      stream: true,
    });

    let fullResponse = '';

    for await (const chunk of stream) {
      const token = chunk.choices[0]?.delta?.content || '';
      if (token) {
        fullResponse += token;
        onToken(token);
      }
    }

    return fullResponse;
  }
}

// server/src/events/ai-handler.ts
import { Socket, Server } from 'socket.io';
import { AIService } from '../services/ai.service';
import { Message } from '../models/message.model';
import { Conversation } from '../models/conversation.model';

const aiService = new AIService();

export function setupAIHandler(io: Server, socket: Socket) {
  socket.on('ai:ask', async (data, callback) => {
    const { conversationId, question } = data;
    const userId = socket.data.userId;

    try {
      // Kullanıcı mesajını kaydet
      const userMessage = await Message.create({
        conversationId,
        sender: userId,
        content: question,
        type: 'text',
        readBy: [userId],
      });

      io.to(conversationId).emit('message:received',
        await userMessage.populate('sender', 'name avatar')
      );

      // Son mesajları context olarak al
      const history = await Message.find({ conversationId })
        .sort({ createdAt: -1 })
        .limit(10)
        .lean();

      // AI yanıtı için placeholder mesaj oluştur
      const aiMessage = await Message.create({
        conversationId,
        sender: userId,
        content: '',
        type: 'ai_response',
        readBy: [userId],
      });

      // Streaming başladı bildirimi
      io.to(conversationId).emit('ai:stream:start', {
        messageId: aiMessage.id,
        conversationId,
      });

      // Streaming yanıt
      const fullResponse = await aiService.generateStreamingResponse(
        question,
        history.reverse(),
        (token) => {
          io.to(conversationId).emit('ai:stream:token', {
            messageId: aiMessage.id,
            token,
          });
        }
      );

      // Final mesajı güncelle
      await Message.findByIdAndUpdate(aiMessage.id, { content: fullResponse });

      io.to(conversationId).emit('ai:stream:end', {
        messageId: aiMessage.id,
        fullContent: fullResponse,
      });

      await Conversation.findByIdAndUpdate(conversationId, {
        lastMessage: aiMessage.id,
        lastActivity: new Date(),
      });

      callback({ status: 'ok' });
    } catch (error) {
      console.error('AI error:', error);
      callback({ status: 'error', message: 'AI yanıt veremedi' });
    }
  });
}

