import { useEffect, useState } from 'react';
import { useSocketStore } from '../stores/socket-store';
import { useChatStore } from '../stores/chat-store';

export function useAIStream() {
  const { socket } = useSocketStore();
  const [streamingMessages, setStreamingMessages] = useState<Record<string, string>>({});

  useEffect(() => {
    if (!socket) return;

    socket.on('ai:stream:start', ({ messageId }) => {
      setStreamingMessages((prev) => ({ ...prev, [messageId]: '' }));
    });

    socket.on('ai:stream:token', ({ messageId, token }) => {
      setStreamingMessages((prev) => ({
        ...prev,
        [messageId]: (prev[messageId] || '') + token,
      }));
    });

    socket.on('ai:stream:end', ({ messageId }) => {
      setStreamingMessages((prev) => {
        const next = { ...prev };
        delete next[messageId];
        return next;
      });
    });

    return () => {
      socket.off('ai:stream:start');
      socket.off('ai:stream:token');
      socket.off('ai:stream:end');
    };
  }, [socket]);

  return { streamingMessages };
}

