import { redis } from '../utils/redis';
import { Socket } from 'socket.io';

const AI_RATE_LIMIT = 10; // Dakikada 10 istek
const AI_RATE_WINDOW = 60; // 60 saniye

export async function checkAIRateLimit(userId: string): Promise<boolean> {
  const key = `ai_rate:${userId}`;
  const current = await redis.incr(key);

  if (current === 1) {
    await redis.expire(key, AI_RATE_WINDOW);
  }

  return current <= AI_RATE_LIMIT;
}

// server/src/utils/prompt-guard.ts
const BLOCKED_PATTERNS = [
  /ignore.*previous.*instructions/i,
  /forget.*system.*prompt/i,
  /you.*are.*now/i,
  /act.*as.*if/i,
];

export function sanitizeUserInput(input: string): string {
  // Prompt injection kalıplarını kontrol et
  for (const pattern of BLOCKED_PATTERNS) {
    if (pattern.test(input)) {
      return '[Güvenlik: Bu tür komutlar engellenmiştir]';
    }
  }

  // Maksimum uzunluk sınırı
  if (input.length > 2000) {
    return input.slice(0, 2000) + '... [kısaltıldı]';
  }

  return input;
}

